/bin/zsh -lc "node --input-type=module <<'JS'
import { readFileSync } from 'node:fs';
import assert from 'node:assert/strict';
const source = readFileSync('math.js', 'utf8');
const { add } = await import("'`data:text/javascript,${encodeURIComponent(source)}`);
assert.equal(add(2, 3), 5);
for (const value of ['"'2', null, undefined, true, {}, [], 2n]) {
  assert.throws(() => add(value, 3), TypeError);
  assert.throws(() => add(2, value), TypeError);
}
console.log('Verified numeric addition and TypeError for non-number arguments in either position.');
JS"

